```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>DVD Bouncing Logo</title>
    <style>
        body {
            margin: 0;
            padding: 0;
            background-color: black;
            overflow: hidden;
            height: 100vh;
            width: 100vw;
        }
        #dvd {
            position: absolute;
            color: white;
            font-family: sans-serif;
            font-weight: bold;
            font-size: 2rem;
            white-space: nowrap;
            user-select: none;
        }
    </style>
</head>
<body>

<div id="dvd">DVD</div>

<script>
    const dvd = document.getElementById('dvd');

    let x = Math.random() * (window.innerWidth - 100);
    let y = Math.random() * (window.innerHeight - 50);
    let xSpeed = 3;
    let ySpeed = 3;

    function animate() {
        const rect = dvd.getBoundingClientRect();

        x += xSpeed;
        y += ySpeed;

        // Check horizontal boundaries
        if (x + rect.width >= window.innerWidth || x <= 0) {
            xSpeed *= -1;
        }

        // Check vertical boundaries
        if (y + rect.height >= window.innerHeight || y <= 0) {
            ySpeed *= -1;
        }

        dvd.style.left = x + 'px';
        dvd.style.top = y + 'px';

        requestAnimationFrame(animate);
    }

    animate();

    // Handle window resize
    window.addEventListener('resize', () => {
        x = Math.min(x, window.innerWidth - dvd.offsetWidth);
        y = Math.min(y, window.innerHeight - dvd.offsetHeight);
    });
</script>

</body>
</html>
